// @ferrum/calc: the platform's pricing engine in the browser — Ferrum's crates/calc built for
// WebAssembly (generated by ./build.sh, committed), so prices, discounts, taxes and rounding come
// out exactly as the server computes them: a till pricing sales offline, live totals in a form.
// Amounts travel as decimal strings, never floats.

import init, { computeTotals } from "./ferrum_calc.js";

/** `on_item_quantity`: `rate` per unit of the line's `tax_qty` (else `qty`), an excise or a fee. */
export type ChargeType = "on_net_total" | "on_previous_row_amount" | "on_previous_row_total" | "actual" | "on_item_quantity";
export type Rounding = "half_up" | "half_even";
/** Each tax row rounded once over the document (the default), or line by line and added up. */
export type TaxRounding = "per_document" | "per_line";

export interface LineIn {
  key: string;
  qty: string;
  /** Unit price before the line's discount (tax-inclusive when an inclusive tax row applies). */
  price: string;
  discount_percent?: string;
  /** Per-line rate overrides by tax row key. */
  tax_rates?: Record<string, string>;
  /** The quantity per-unit taxes count (the line in stock units); `qty` when unset. */
  tax_qty?: string | null;
}

export interface TaxIn {
  key: string;
  charge_type: ChargeType;
  rate?: string;
  amount?: string;
  row_ref?: number | null;
  included_in_price?: boolean;
  deduct?: boolean;
  /** Worked out and reported, never charged to the party: left out of the totals. */
  reverse_charge?: boolean;
}

export interface CalcInput {
  precision: number;
  base_precision?: number | null;
  conversion_rate?: string;
  rounding?: Rounding;
  lines: LineIn[];
  taxes?: TaxIn[];
  discount?: { kind: "percent" | "amount"; value: string } | null;
  round_total_to?: string | null;
  tax_rounding?: TaxRounding;
}

export interface CalcOutput {
  lines: { key: string; rate: string; amount: string; net_amount: string; taxes: string[] }[];
  taxes: { key: string; tax_amount: string; deduct: boolean; reverse_charge: boolean; total: string }[];
  total: string;
  discount_amount: string;
  net_total: string;
  total_taxes: string;
  grand_total: string;
  rounding_adjustment: string;
  rounded_total: string;
}

/** The engine's file, for warming a cache (an offline app's worker) before it is needed. */
export const engineUrl = new URL("./ferrum_calc_bg.wasm", import.meta.url).href;

let loading: Promise<unknown> | null = null;

/** Loads the engine once (about 320 KB, compiled by the browser; the page's policy allows it). */
export function loadEngine(source?: BufferSource): Promise<void> {
  const now = loading ?? init(source ? { module_or_path: source } : undefined);
  // A failed load (offline before the engine was ever cached) is tried again next time.
  loading = now.catch((e: unknown) => {
    loading = null;
    throw e;
  });
  return loading.then(() => undefined);
}

/** Totals for `input`, as the server computes them; throws the engine's refusal (an overflow, a
 *  tax row that refers to a later one). */
export async function calculate(input: CalcInput): Promise<CalcOutput> {
  await loadEngine();
  const out = JSON.parse(computeTotals(JSON.stringify(input))) as CalcOutput | { error: string };
  if ("error" in out) throw new Error(out.error);
  return out;
}
